INSERT INTO threshold_rule (threshold_id, applies_to, threshold_days, day_basis, meaning) VALUES ('THR-001', 'In Transit to Vendor', 30, 'CALENDAR', 'Collected by the vendor but not yet receipted into a warehouse. Pickup SLA is 2 business days, so 30 calendar days is far beyond any legitimate delay - treat as possibly lost in transit.');
INSERT INTO threshold_rule (threshold_id, applies_to, threshold_days, day_basis, meaning) VALUES ('THR-002', 'With Business', 90, 'CALENDAR', 'Recalled to the business and not yet returned. There is no contractual SLA; this is a borrowing convention. Below 90 days the file is simply in use.');
INSERT INTO threshold_rule (threshold_id, applies_to, threshold_days, day_basis, meaning) VALUES ('THR-003', 'Request open', 0, 'CALENDAR', 'A request with no completion past its own sla_due_date. No grace period - the due date is the threshold.');
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('Created', 'Carton registered by business; not yet collected', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('Pickup Requested', 'Pickup request raised, awaiting vendor', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('In Transit to Vendor', 'Collected by vendor, not yet receipted', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('In Storage', 'Held at vendor warehouse', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('Retrieval Requested', 'Retrieval raised, awaiting delivery', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('With Business', 'Physically with the requesting department', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('Return Requested', 'Return to vendor raised', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('Destruction Requested', 'Awaiting approval', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('Approved for Destruction', 'Approved, awaiting vendor execution', false);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('Destroyed', 'Terminal state, certificate issued', true);
INSERT INTO carton_status (status_code, meaning, is_terminal) VALUES ('Missing', 'Exception state raised by reconciliation', false);
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('CARTON_CREATED', 'A carton is registered and its files indexed. The first event in every carton''s life.', false, 'BUSINESS', 'Created', 'No', '{"event_type": "CARTON_CREATED", "meaning": "A carton is registered and its files indexed. The first event in every carton''s life.", "raised_by": "Business User", "request_required": "No", "resulting_carton_status": "Created", "changes_location": "No", "notes": "Nothing may precede this event for a given carton."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('PICKUP_REQUESTED', 'The business asks the vendor to collect the carton and take it into storage.', false, 'BUSINESS', 'Pickup Requested', 'Yes - PICKUP', '{"event_type": "PICKUP_REQUESTED", "meaning": "The business asks the vendor to collect the carton and take it into storage.", "raised_by": "Business User", "request_required": "Yes - PICKUP", "resulting_carton_status": "Pickup Requested", "changes_location": "No", "notes": "Starts the pickup SLA clock. The carton has not moved yet."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('PICKED_UP_BY_VENDOR', 'The vendor confirms physical collection from the business premises.', true, 'VENDOR', 'In Transit to Vendor', 'Yes - PICKUP', '{"event_type": "PICKED_UP_BY_VENDOR", "meaning": "The vendor confirms physical collection from the business premises.", "raised_by": "Vendor User", "request_required": "Yes - PICKUP", "resulting_carton_status": "In Transit to Vendor", "changes_location": "Yes - leaves the office", "notes": "Collection is NOT receipt. A carton sitting in this state for days is an exception."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('RECEIVED_AT_WAREHOUSE', 'The vendor confirms the carton has arrived and been shelved at the warehouse.', true, 'VENDOR', 'In Storage', 'Yes - PICKUP or RETURN', '{"event_type": "RECEIVED_AT_WAREHOUSE", "meaning": "The vendor confirms the carton has arrived and been shelved at the warehouse.", "raised_by": "Vendor User", "request_required": "Yes - PICKUP or RETURN", "resulting_carton_status": "In Storage", "changes_location": "Yes - arrives at a warehouse", "notes": "Only now is the carton billable for storage and eligible for retrieval."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('RETRIEVAL_REQUESTED', 'The business asks for a stored carton to be sent back to them temporarily.', false, 'BUSINESS', 'Retrieval Requested', 'Yes - RETRIEVAL', '{"event_type": "RETRIEVAL_REQUESTED", "meaning": "The business asks for a stored carton to be sent back to them temporarily.", "raised_by": "Business User", "request_required": "Yes - RETRIEVAL", "resulting_carton_status": "Retrieval Requested", "changes_location": "No", "notes": "Valid only from In Storage. Never valid against a destroyed carton."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('DELIVERED_TO_BUSINESS', 'The vendor confirms delivery and the business acknowledges physical receipt.', true, 'VENDOR', 'With Business', 'Yes - RETRIEVAL', '{"event_type": "DELIVERED_TO_BUSINESS", "meaning": "The vendor confirms delivery and the business acknowledges physical receipt.", "raised_by": "Vendor User", "request_required": "Yes - RETRIEVAL", "resulting_carton_status": "With Business", "changes_location": "Yes - leaves the warehouse", "notes": "The carton is now outside the warehouse and is not billed for storage."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('RETURN_REQUESTED', 'The business has finished with the carton and asks the vendor to take it back.', false, 'BUSINESS', 'Return Requested', 'Yes - RETURN', '{"event_type": "RETURN_REQUESTED", "meaning": "The business has finished with the carton and asks the vendor to take it back.", "raised_by": "Business User", "request_required": "Yes - RETURN", "resulting_carton_status": "Return Requested", "changes_location": "No", "notes": "Valid only from With Business. Completion is a RECEIVED_AT_WAREHOUSE event."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('DESTRUCTION_REQUESTED', 'The owner asks for the carton to be destroyed because retention has expired.', false, 'BUSINESS', 'Destruction Requested', 'Yes - DESTRUCTION', '{"event_type": "DESTRUCTION_REQUESTED", "meaning": "The owner asks for the carton to be destroyed because retention has expired.", "raised_by": "Business User", "request_required": "Yes - DESTRUCTION", "resulting_carton_status": "Destruction Requested", "changes_location": "No", "notes": "Must be blocked if retention has not expired, a hold is active, or the carton is not in storage."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('DESTRUCTION_APPROVED', 'A compliance officer authorises the destruction.', false, 'COMPLIANCE', 'Approved for Destruction', 'Yes - DESTRUCTION', '{"event_type": "DESTRUCTION_APPROVED", "meaning": "A compliance officer authorises the destruction.", "raised_by": "Compliance Officer", "request_required": "Yes - DESTRUCTION", "resulting_carton_status": "Approved for Destruction", "changes_location": "No", "notes": "Never the same person who requested it. This is the internal gate before the vendor acts."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('DESTROYED', 'The vendor physically destroys the carton and issues a certificate.', true, 'VENDOR', 'Destroyed', 'Yes - DESTRUCTION', '{"event_type": "DESTROYED", "meaning": "The vendor physically destroys the carton and issues a certificate.", "raised_by": "Vendor User", "request_required": "Yes - DESTRUCTION", "resulting_carton_status": "Destroyed", "changes_location": "Yes - leaves the warehouse permanently", "notes": "Terminal. No event may follow it for that carton. Storage billing stops this month."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('INTER_WAREHOUSE_TRANSFER', 'The vendor moves a carton between two of their own warehouses.', true, 'VENDOR', 'In Storage', 'No', '{"event_type": "INTER_WAREHOUSE_TRANSFER", "meaning": "The vendor moves a carton between two of their own warehouses.", "raised_by": "Vendor User", "request_required": "No", "resulting_carton_status": "In Storage", "changes_location": "Yes - warehouse to warehouse", "notes": "Status is unchanged; only location moves. Rare, but it breaks naive location logic."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('LEGAL_HOLD_APPLIED', 'Compliance freezes the carton against destruction for a legal or regulatory matter.', false, 'COMPLIANCE', NULL, 'No', '{"event_type": "LEGAL_HOLD_APPLIED", "meaning": "Compliance freezes the carton against destruction for a legal or regulatory matter.", "raised_by": "Compliance Officer", "request_required": "No", "resulting_carton_status": "unchanged", "changes_location": "No", "notes": "Proof that not every event changes status. resulting_status is blank on this row."}');
INSERT INTO event_type (event_type, meaning, changes_custody, expected_role, resulting_status, request_requirement, source_definition) VALUES ('LEGAL_HOLD_RELEASED', 'Compliance lifts the freeze; the carton returns to normal retention treatment.', false, 'COMPLIANCE', NULL, 'No', '{"event_type": "LEGAL_HOLD_RELEASED", "meaning": "Compliance lifts the freeze; the carton returns to normal retention treatment.", "raised_by": "Compliance Officer", "request_required": "No", "resulting_carton_status": "unchanged", "changes_location": "No", "notes": "Blank resulting_status, as above. The release itself is an audit record."}');
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('REQUEST_ACKNOWLEDGED', 'Vendor acknowledgment', 'VENDOR');
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('REQUEST_REJECTED', 'Rejected instruction or approval', NULL);
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('REQUEST_CANCELLED', 'Business cancellation', 'BUSINESS');
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('FILE_INDEXED', 'File index added or corrected', 'BUSINESS');
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('CERTIFICATE_LODGED', 'Evidence attachment, not a physical carton movement', 'VENDOR');
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('REFERENCE_CHANGED', 'Before and after configuration values', NULL);
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('USER_ACCESS_CHANGED', 'Access assignment or deactivation', 'FACILITIES');
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('EXCEPTION_UPDATED', 'Investigation or resolution', NULL);
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('RECONCILIATION_RUN', 'Recorded reconciliation request', 'FACILITIES');
INSERT INTO event_type (event_type, meaning, expected_role) VALUES ('CORRECTION_RECORDED', 'Compensating evidence; privileged reviewed process', NULL);
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Created', 'PICKUP_REQUESTED', 'Pickup Requested');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Pickup Requested', 'PICKED_UP_BY_VENDOR', 'In Transit to Vendor');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('In Transit to Vendor', 'RECEIVED_AT_WAREHOUSE', 'In Storage');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('In Storage', 'RETRIEVAL_REQUESTED', 'Retrieval Requested');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Retrieval Requested', 'DELIVERED_TO_BUSINESS', 'With Business');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('With Business', 'RETURN_REQUESTED', 'Return Requested');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Return Requested', 'RECEIVED_AT_WAREHOUSE', 'In Storage');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('In Storage', 'DESTRUCTION_REQUESTED', 'Destruction Requested');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Destruction Requested', 'DESTRUCTION_APPROVED', 'Approved for Destruction');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Approved for Destruction', 'DESTROYED', 'Destroyed');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('In Storage', 'INTER_WAREHOUSE_TRANSFER', 'In Storage');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Pickup Requested', 'REQUEST_CANCELLED', 'Created');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Retrieval Requested', 'REQUEST_CANCELLED', 'In Storage');
INSERT INTO lifecycle_transition (from_status, event_type, to_status) VALUES ('Destruction Requested', 'REQUEST_REJECTED', 'In Storage');
